window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"D-RSH2Hrz7k","speaker":"King Abdullah II ibn Al Hussein","role":"King","country":"Jordan","region":"Middle East","url":"https://www.youtube.com/watch?v=D-RSH2Hrz7k","date":"20260922","title":"🇯🇴 Jordan - King Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1185,"words":1809,"counts":{"claims":31,"promises":2,"attacks":11},"topics":[{"topic":"Israel-Gaza","share":0.272,"seconds":322},{"topic":"Israel-Palestine violence","share":0.0631,"seconds":75},{"topic":"Humanitarian suffering","share":0.062,"seconds":74},{"topic":"Jerusalem holy sites","share":0.0611,"seconds":72},{"topic":"Iran","share":0.0603,"seconds":72},{"topic":"Gaza ceasefire","share":0.0581,"seconds":69},{"topic":"Global attention","share":0.0572,"seconds":68},{"topic":"Israel-Syria","share":0.0532,"seconds":63},{"topic":"Ceremony","share":0.0529,"seconds":63},{"topic":"Military force limitations","share":0.0524,"seconds":62},{"topic":"Gaza settlements","share":0.0522,"seconds":62},{"topic":"Jordan diplomacy","share":0.0519,"seconds":62},{"topic":"Arab Peace Initiative","share":0.0518,"seconds":61},{"topic":"Israel settlements","share":0.0516,"seconds":61}],"timeline":[[0,63,"Ceremony"],[65,133,"Global attention"],[135,209,"Humanitarian suffering"],[210,282,"Iran"],[284,353,"Gaza ceasefire"],[356,418,"Gaza settlements"],[418,480,"Israel-Gaza"],[482,557,"Israel-Palestine violence"],[559,626,"Israel-Gaza"],[628,689,"Israel settlements"],[691,753,"Arab Peace Initiative"],[755,818,"Israel-Gaza"],[820,884,"Israel-Gaza"],[886,951,"Israel-Gaza"],[953,1016,"Israel-Syria"],[1018,1090,"Jerusalem holy sites"],[1092,1154,"Jordan diplomacy"],[1156,1218,"Military force limitations"],[1219,1233,null]],"stances":{"Ceremony":"King Abdullah II begins his address by acknowledging the universal human tendency to view current challenges as unique.","Global attention":"King Abdullah II states that declining global attention spans have made the allocation of focus a critical geopolitical factor determining which conflicts receive diplomatic support.","Humanitarian suffering":"King Abdullah II states that protracted conflicts in his region are deepening humanitarian suffering and warns that neglecting these issues shapes the future.","Iran":"King Abdullah II states that the Iran war demonstrates how quickly instability can disrupt trade, investment, and lives beyond the region.","Gaza ceasefire":"King Abdullah II states that international law is being ignored and criticizes the Israeli government for continuing attacks despite a ceasefire.","Gaza settlements":"King Abdullah II asserts that the situation in Gaza and the West Bank represents a fundamental shift involving an attempt to erase Palestinian life and impose new territorial realities, rather than temporary measures or mere escalation.","Israel-Gaza":"King Abdullah II characterizes Israel's actions in the West Bank as forcible transfer and de facto annexation rather than lawful security measures.","Israel-Palestine violence":"King Abdullah II asserts that the situation involves systematic attacks by Israeli settlers on Palestinians, often with the complicity or participation of Israeli soldiers, rather than isolated incidents.","Israel settlements":"King Abdullah II asserts that Israeli settlement expansion and land seizures have cemented the rejection of Palestinian statehood, making a viable Palestinian state impossible.","Arab Peace Initiative":"King Abdullah II states that the Arab Peace Initiative of 2002 remains valid and that the lack of a peace agreement is due to the current Israeli government's unwillingness to accept it.","Israel-Syria":"King Abdullah II warns that the international community must not allow Israel's antagonistic actions in southern Syria to continue unchecked.","Jerusalem holy sites":"King Abdullah II states that Jordan will continue to uphold the Hashemite custodianship and historic legal status quo at Muslim and Christian holy sites in Jerusalem.","Jordan diplomacy":"King Abdullah II states that Jordan remains a reliable partner committed to principles and human values, with a bias towards diplomacy that should not be mistaken for weakness.","Military force limitations":"King Abdullah II states that military force is incapable of solving humanitarian, environmental, and technological challenges and emphasizes the necessity of trust and institutions."},"claims":[{"t":56,"quote":"every generation believes the challenges they face are unmatched. Perhaps for us that is true.","topic":"Ceremony","kind":"fact"},{"t":85,"quote":"One study shows that average screen attention has fallen from 2.5 minutes in to just 47 seconds today.","topic":"Global attention","kind":"number"},{"t":201,"quote":"In my region, from Lebanon to Yemen to Sudan, protracted conflict is deepening humanitarian suffering.","topic":"Humanitarian suffering","kind":"fact"},{"t":229,"quote":"The Iran war has shown how quickly instability can disrupt trade, investment, and lives beyond the region.","topic":"Iran","kind":"fact"},{"t":243,"quote":"For decades, I've stood before this assembly and warned of the dangers of leaving the Palestinian Israeli conflict","topic":"Iran","kind":"self_credit"},{"t":315,"quote":"In the first 300 days of the so-called ceasefire, at least 300 Palestinian children were killed.","topic":"Gaza ceasefire","kind":"number"},{"t":370,"quote":"An attempt to erase Palestinian life and impose a new territorial reality in Gaza.","topic":"Gaza settlements","kind":"fact"},{"t":406,"quote":"This is a fundamental shift. What was once a creeping process has exploded into something far more Settler violence is rampant.","topic":"Gaza settlements","kind":"fact"},{"t":418,"quote":"Palestinians are being beaten, shot, and property destroyed, families driven from their land.","topic":"Israel-Gaza","kind":"fact"},{"t":454,"quote":"Demolishing Palestinian homes to expand illegal settlements is not law It is forcible transfer.","topic":"Israel-Gaza","kind":"fact"},{"t":487,"quote":"Systematic attacks on Palestinian are not settler unrest.","topic":"Israel-Palestine violence","kind":"fact"},{"t":517,"quote":"Israeli soldiers stand by as settlers attack Palestinians, often protecting the attackers or joining them.","topic":"Israel-Palestine violence","kind":"fact"},{"t":526,"quote":"They have blocked ambulances from reaching the injured.","topic":"Israel-Palestine violence","kind":"fact"},{"t":576,"quote":"It is elements of a single policy to compel an entire population to leave their land. And there is a name for that. forced displacement and that is a war crime.","topic":"Israel-Gaza","kind":"fact"},{"t":609,"quote":"The first is that Gaza and the West Bank are separate stories. They are not. They are two fronts of the same Israeli In both, Palestinians are being killed.","topic":"Israel-Gaza","kind":"fact"},{"t":677,"quote":"Since Oslo, the map has changed piece by piece, settlement by settlement.","topic":"Israel settlements","kind":"fact"},{"t":691,"quote":"The Arab Peace Initiative of 2002 offered Israel normalization with 57 Arab and Muslim states including Iran and Iraq at the time in exchange for peace and Palestinian statethood.","topic":"Arab Peace Initiative","kind":"fact"},{"t":715,"quote":"For over 20 years, that offer has stood.","topic":"Arab Peace Initiative","kind":"fact"},{"t":766,"quote":"It has also tried to cast this conflict as a war of religions. Islam on one side, Judaism and Christianity on the other.","topic":"Israel-Gaza","kind":"fact"},{"t":781,"quote":"This is about whether Palestinians, Muslims, and Christians are entitled to the same rights as everyone else.","topic":"Israel-Gaza","kind":"fact"},{"t":835,"quote":"Yet with Israel, resolutions end where they began on paper.","topic":"Israel-Gaza","kind":"fact"},{"t":848,"quote":"This result is a state without restraint. This government's sense of impunity has reached terrifying levels.","topic":"Israel-Gaza","kind":"fact"},{"t":895,"quote":"Repeated incursions, creeping territorial expansion, new facts imposed on the ground, including around vital water resources.","topic":"Israel-Gaza","kind":"fact"},{"t":956,"quote":"if Israel continues its antagonistic approach in southern Syria, will the international community stand and let that happen?","topic":"Israel-Syria","kind":"fact"},{"t":1006,"quote":"We are strengthening connections from the Gulf to the Mediterranean as a hub for trade, industry, and technology while responding to humanitarian crisis.","topic":"Israel-Syria","kind":"self_credit"},{"t":1031,"quote":"we are protecting Christianity in its communities and heritage in its native and historic land while promoting the true image of Islam against the voices of hate","topic":"Jerusalem holy sites","kind":"fact"},{"t":1084,"quote":"Jordan is striving to build a different model, principled, open, and steady","topic":"Jerusalem holy sites","kind":"fact"},{"t":1092,"quote":"At a time when certainty is rare, and politics can shift by the day, a country the world can count on.","topic":"Jordan diplomacy","kind":"fact"},{"t":1102,"quote":"true to our principles, true to our word, ready to talk to everyone, and ready to work with anyone seeking peace.","topic":"Jordan diplomacy","kind":"self_credit"},{"t":1156,"quote":"Military force cannot deliver meaningful solutions. It cannot feed the hungry, return the displaced, or build peace.","topic":"Military force limitations","kind":"fact"},{"t":1165,"quote":"Nor can it repair our planet, manage mass migration, or guide technological","topic":"Military force limitations","kind":"fact"}],"promises":[{"t":945,"quote":"We will protect our security, our water, and the interests of our people.","topic":"Israel-Gaza","kind":"promise"},{"t":1060,"quote":"We will continue to support Palestinian resilience. We will continue supporting Anroa and we will continue to uphold the hashmite custodianship and historic and legal status quo at Muslim and Christian holy sites in Jerusalem","topic":"Jerusalem holy sites","kind":"promise"}],"attacks":[{"t":338,"quote":"this Israeli government keeps moving the goalposts, continuing its attacks and destruction of civilian infrastructure, refusing to withdraw, and squeezing Palestinians into barely a third of Gazda.","topic":"Gaza ceasefire","target":"Israel"},{"t":442,"quote":"It is time to see what is happening for what it really is. Because when the language is sanitized, the actions become normalized.","topic":"Israel-Gaza","target":"International Community"},{"t":482,"quote":"It is a system of subjugation.","topic":"Israel-Palestine violence","target":"Israel"},{"t":537,"quote":"And when soldiers watch, enable, and sometimes even participate in violence against civilians, this is no longer about a handful of","topic":"Israel-Palestine violence","target":"Israel"},{"t":734,"quote":"This Israeli government, this Israeli government understands the power of attention. And lately, it has not liked the attention it's been getting.","topic":"Arab Peace Initiative","target":"Israel"},{"t":755,"quote":"When confronted with evidence of rather than change the course, it opts for distraction, discrediting its","topic":"Israel-Gaza","target":"Israel"},{"t":798,"quote":"Distractions will not fly anymore.","topic":"Israel-Gaza","target":"Unnamed opponents"},{"t":853,"quote":"This government's sense of impunity has reached terrifying levels.","topic":"Israel-Gaza","target":"Israel"},{"t":878,"quote":"This Israeli government's expansionist is now a regional threat.","topic":"Israel-Gaza","target":"Israel"},{"t":905,"quote":"Step by calculated step, Israel is testing how far it can go.","topic":"Israel-Gaza","target":"Israel"},{"t":912,"quote":"And every time the international community looks away, Israel learns that it can go even further across border lines and legal","topic":"Israel-Gaza","target":"International Community"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":"Ceremony","text":"The assembly will now hear an address by his majesty Abdullah II al Hussein, king of the Hashimite Kingdom of Jordan. I request protocol to escort his majesty and invite him to address the assembly. Rahman Rahim, Mr. President, Mr. Secretary General, your excellencies, every generation believes the challenges they face are unmatched. Perhaps for us that is true."},{"t":65,"topic":"Global attention","text":"We are at a unique moment in history. The scale of knowledge and the speed of change are unprecedented. Every day brings another crisis, another tragedy, another emergency demanding our attention. One study shows that average screen attention has fallen from 2.5 minutes in to just 47 seconds today. Of course, a screen is not the world, but that says something about our world that attention has become a scarce asset and where we choose to direct it has never mattered more. And in this chamber, attention is more than a cognitive It is a geopolitical one. It determines which conflicts receive sustained diplomacy and which fade from the agenda."},{"t":135,"topic":"Humanitarian suffering","text":"Whether a ceasefire holds after the cameras leave, whether humanitarian suffering remains intolerable or becomes familiar, and whether the world steps up or and strolls away, history rarely catches us entirely by More often it catches us focused Economic disparity, food insecurity, climate change disasters. None of these challenged emerged The warning signs have been there. The question is whether our attention lasts long enough to act. and what we neglect has a habit of shaping our future. Your excellencies, we see the cost of that neglect every In my region, from Lebanon to Yemen to Sudan, protracted conflict is deepening humanitarian suffering."},{"t":210,"topic":"Iran","text":"And if anyone had any doubt that a crisis in our part of the world stays just look at the energy and grocery bills of ordinary families from Mumbai to Madrid to Minnesota. The Iran war has shown how quickly instability can disrupt trade, investment, and lives beyond the region. And then there is Gaza. For decades, I've stood before this assembly and warned of the dangers of leaving the Palestinian Israeli conflict But the international community chose to manage the conflict, not confront it. And every new Israeli violation was treated as temporary, diverting attention from the reality being created on the ground until temporary became permanent and permanent became policy."},{"t":284,"topic":"Gaza ceasefire","text":"Of course, this is not the world's only but one of the world's longest running forces a basic question. If international law can be ignored for then what exactly is that law worth? And how can we enforce it if we won't even call out its violations? In Gaza, the evidence is overwhelming. In the first 300 days of the so-called ceasefire, at least 300 Palestinian children were killed. Jordan's field hospitals have also been President Trump has pushed hard for peace and a path to end this war. But this Israeli government keeps moving the goalposts, continuing its attacks and destruction of civilian infrastructure, refusing to withdraw, and squeezing Palestinians into barely a third of Gazda."},{"t":356,"topic":"Gaza settlements","text":"This can no longer be dismissed as temporary military measures or a consequence of war. Accountability begins when we call things for what they are. An attempt to erase Palestinian life and impose a new territorial reality in Gaza. And while the world has been focused on something extraordinarily dangerous is unfolding in the West Bank. Some may think we have seen this before. Settlements, violence, displacement, more of the same, but it is not. Nor is it simply an escalation. This is a fundamental shift. What was once a creeping process has exploded into something far more Settler violence is rampant."},{"t":418,"topic":"Israel-Gaza","text":"Palestinians are being beaten, shot, and property destroyed, families driven from their land. And Israel is tightening its grip on more of the West Bank, seizing land, expanding settlements, and pushing the Palestinians out. It is time to see what is happening for what it really is. Because when the language is sanitized, the actions become normalized. Demolishing Palestinian homes to expand illegal settlements is not law It is forcible transfer. Appropriating occupied land is not land It is de facto annexation. A choking network of checkpoints and is not security infrastructure."},{"t":482,"topic":"Israel-Palestine violence","text":"It is a system of subjugation. Systematic attacks on Palestinian are not settler unrest. The Israeli government criticizes the violence before the international They call those responsible a handful of They assure us that Israel is a country governed by law. Yet what's happening on the ground says Israeli soldiers stand by as settlers attack Palestinians, often protecting the attackers or joining them. They have blocked ambulances from reaching the injured. They have targeted international journalists who are trying to say the And when soldiers watch, enable, and sometimes even participate in violence against civilians, this is no longer about a handful of And the question is no longer whether a few extremists are breaking the law."},{"t":559,"topic":"Israel-Gaza","text":"The question is, is this the behavior of a democratic state governed by law? What is unfolding across the West Bank is not a series of isolated acts. It is elements of a single policy to compel an entire population to leave their land. And there is a name for that. forced displacement and that is a war crime. Your excellencies, if we are to resolve the Palestinian Israeli conflict, the world must abandon some illusions. The first is that Gaza and the West Bank are separate stories. They are not. They are two fronts of the same Israeli In both, Palestinians are being killed."},{"t":628,"topic":"Israel settlements","text":"In both, the reality on the ground is being remade. Gaza through destruction, the West Bank through de facto The objective is the same. to make a viable Palestinian state impossible. Another illusion is that this Israeli leadership's rejection of Palestinian statethood is a position that might yet It is not. It is cemented on the ground. This government has been accelerating settlements and land seizures, but it began long before. Since Oslo, the map has changed piece by piece, settlement by settlement. And the most dangerous illusion that the Arab world never sought peace."},{"t":691,"topic":"Arab Peace Initiative","text":"The Arab Peace Initiative of 2002 offered Israel normalization with 57 Arab and Muslim states including Iran and Iraq at the time in exchange for peace and Palestinian statethood. For over 20 years, that offer has stood. The obstacle hasn't been the absence of a partner for peace, but the absence of an Israeli government willing to accept it. This Israeli government, this Israeli government understands the power of attention. And lately, it has not liked the attention it's been getting."},{"t":755,"topic":"Israel-Gaza","text":"When confronted with evidence of rather than change the course, it opts for distraction, discrediting its It has also tried to cast this conflict as a war of religions. Islam on one side, Judaism and Christianity on the other. It is not. This is about whether Palestinians, Muslims, and Christians are entitled to the same rights as everyone else. Distractions will not fly anymore. People across the world are paying The question now is will we act because the world's political inaction is not for lack of options. So let's call it for what it is."},{"t":820,"topic":"Israel-Gaza","text":"A choice. We have tools. Sanctions, asset freezes, embargos, diplomatic isolation, and we have a record of using them Yet with Israel, resolutions end where they began on paper. This result is a state without restraint. This government's sense of impunity has reached terrifying levels. It no longer feels compelled to ask, \"Can we get away with this?\" It already knows the answer. And that is precisely why no one in this assembly should assume its ambition stop at Palestine. This Israeli government's expansionist is now a regional threat."},{"t":886,"topic":"Israel-Gaza","text":"And today, Syria is the warning the international community is choosing not to see. Repeated incursions, creeping territorial expansion, new facts imposed on the ground, including around vital water resources. Step by calculated step, Israel is testing how far it can go. And every time the international community looks away, Israel learns that it can go even further across border lines and legal For Jordan, there is no ambiguity. Any threat to our northern border or our water security is a threat to our national security. Jordan will not look away. We will protect our security, our water, and the interests of our people."},{"t":953,"topic":"Israel-Syria","text":"And the question here is, if Israel continues its antagonistic approach in southern Syria, will the international community stand and let that happen? Your excellencies, some things demand our immediate attention, others demand sustained Injustice demands both. Jordan understands this all too well. We know what it means to live in a region where one crisis arrives before the last one has receded. And we know that we cannot choose between responding to the emergency before us and building the future beyond So we're doing both. We are strengthening connections from the Gulf to the Mediterranean as a hub for trade, industry, and technology while responding to humanitarian crisis."},{"t":1018,"topic":"Jerusalem holy sites","text":"We are confronting terrorism in the region and beyond. While developing our own defenses and remaining a front line against threats like dichotics, we are protecting Christianity in its communities and heritage in its native and historic land while promoting the true image of Islam against the voices of hate. And through it all, we will not abandon our commitment to a just peace. We will continue to support Palestinian resilience. We will continue supporting Anroa and we will continue to uphold the hashmite custodianship and historic and legal status quo at Muslim and Christian holy sites in Jerusalem. Most importantly, Jordan is striving to build a different model, principled, open, and steady."},{"t":1092,"topic":"Jordan diplomacy","text":"At a time when certainty is rare, and politics can shift by the day, a country the world can count on. true to our principles, true to our word, ready to talk to everyone, and ready to work with anyone seeking peace. our bias towards diplomacy will never supersede our commitment to human values and should not be taken for granted or mistaken for weakness. My friends, whether in Gaza, Sudan, Ukraine, or anywhere, people live with war, displacement, and fear. Whether crisis began weeks ago or has endured for decades, our principles cannot change with the world's attention."},{"t":1156,"topic":"Military force limitations","text":"Military force cannot deliver meaningful solutions. It cannot feed the hungry, return the displaced, or build peace. Nor can it repair our planet, manage mass migration, or guide technological That requires institutions that command And it requires trust. Trust between nations, trust in agreements, trust that rules will actually be enforced. Destroy that trust and every challenge becomes harder. Preserve it and cooperation becomes possible. And in a world competing for our attention, we must be deliberate about where we direct it and vigilant about what seeks to distract it. The future is shaped not only by what we do, but what we choose to ignore."},{"t":1219,"topic":null,"text":"Thank you. &gt;&gt; On on behalf of the assembly, I wish to thank the king of the Hashemid Kingdom of Jordan."}],"compare":[{"topic":"Israel–Palestine","share":0.5893,"mean":0.0496,"rank":2,"others":76},{"topic":"Middle East","share":0.1109,"mean":0.0068,"rank":3,"others":19},{"topic":"Humanitarian Aid","share":0.0655,"mean":0.0016,"rank":4,"others":5},{"topic":"Iran","share":0.0637,"mean":0.0135,"rank":22,"others":25},{"topic":"International Law & Order","share":0.0604,"mean":0.0604,"rank":77,"others":102},{"topic":"Nuclear Disarmament","share":0.0553,"mean":0.0038,"rank":9,"others":9},{"topic":"Jordan","share":0.0548,"mean":0.0,"rank":1,"others":0}]};
